package pl.inf04.temperatury;

import java.util.Locale;
import javafx.fxml.FXML;
import javafx.scene.control.Label;
import javafx.scene.control.TextField;

public class MainController {

    @FXML
    private TextField txtCelsjusz;

    @FXML
    private Label lblWynik;

    @FXML
    private void onPrzelicz() {
        String tekst = txtCelsjusz.getText().trim().replace(',', '.');
        try {
            double c = Double.parseDouble(tekst);
            double f = c * 9 / 5 + 32;
            lblWynik.setText(String.format(Locale.US, "%.1f °C = %.1f °F", c, f));
        } catch (NumberFormatException e) {
            lblWynik.setText("Podaj poprawną liczbę");
        }
    }
}

