package pl.inf04.temperatury

import android.os.Bundle
import android.widget.Button
import android.widget.EditText
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import java.util.Locale

class MainActivity : AppCompatActivity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        val etCelsjusz = findViewById<EditText>(R.id.etCelsjusz)
        val btnPrzelicz = findViewById<Button>(R.id.btnPrzelicz)
        val tvWynik = findViewById<TextView>(R.id.tvWynik)

        btnPrzelicz.setOnClickListener {
            val c = etCelsjusz.text.toString().trim().replace(',', '.').toDoubleOrNull()
            if (c == null) {
                tvWynik.text = "Podaj poprawną liczbę"
            } else {
                val f = c * 9 / 5 + 32
                tvWynik.text = String.format(Locale.US, "%.1f °C = %.1f °F", c, f)
            }
        }
    }
}

