import { useState } from 'react';

export default function App() {
  const [celsjusz, setCelsjusz] = useState('');
  const [wynik, setWynik] = useState('');

  function przelicz() {
    const tekst = celsjusz.trim().replace(',', '.');
    const c = Number(tekst);
    if (tekst === '' || Number.isNaN(c)) {
      setWynik('Podaj poprawną liczbę');
      return;
    }
    const f = (c * 9) / 5 + 32;
    setWynik(`${c.toFixed(1)} °C = ${f.toFixed(1)} °F`);
  }

  return (
    <div>
      <label htmlFor="celsjusz">Temperatura w °C: </label>
      <input id="celsjusz" value={celsjusz} onChange={(e) => setCelsjusz(e.target.value)} />
      <button id="przelicz" onClick={przelicz}>Przelicz</button>
      <p id="wynik">{wynik}</p>
    </div>
  );
}

