import { useState, ChangeEvent } from 'react';

export default function App() {
  const [celsjusz, setCelsjusz] = useState<string>('');
  const [wynik, setWynik] = useState<string>('');

  const przelicz = (): void => {
    const tekst = celsjusz.trim().replace(',', '.');
    const c: number = Number(tekst);
    if (tekst === '' || Number.isNaN(c)) {
      setWynik('Podaj poprawną liczbę');
      return;
    }
    const f: number = (c * 9) / 5 + 32;
    setWynik(`${c.toFixed(1)} °C = ${f.toFixed(1)} °F`);
  };

  const zmiana = (e: ChangeEvent<HTMLInputElement>): void => setCelsjusz(e.target.value);

  return (
    <div>
      <label htmlFor="celsjusz">Temperatura w °C: </label>
      <input id="celsjusz" value={celsjusz} onChange={zmiana} />
      <button id="przelicz" onClick={przelicz}>Przelicz</button>
      <p id="wynik">{wynik}</p>
    </div>
  );
}

